def get_all_ext_neighbors(grid, r, c):
    neighbors = []
    # Top
    if r > 0:
        for col_c in range(c, c+3):
            if 0 <= r-1 < len(grid) and 0 <= col_c < len(grid[0]):
                neighbors.append((r-1, col_c))
    # Bottom
    if r+2 < len(grid):
        for col_c in range(c, c+3):
            if 0 <= r+2 < len(grid) and 0 <= col_c < len(grid[0]):
                neighbors.append((r+2, col_c))
    # Left
    if c > 0:
        for row_r in range(r, r+2):
            if 0 <= row_r < len(grid) and 0 <= c-1 < len(grid[0]):
                neighbors.append((row_r, c-1))
    # Right
    if c+3 < len(grid[0]):
        for row_r in range(r, r+2):
            if 0 <= row_r < len(grid) and 0 <= c+3 < len(grid[0]):
                neighbors.append((row_r, c+3))
    return neighbors

