def is_isolated_2x3(grid, r, c):
    """Check if 2x3 block at (r,c) is completely surrounded by zeros"""
    ext_neighbors = []
    if r > 0:
        for col_c in range(c, c+3):
            ext_neighbors.append((r-1, col_c))
    if r+2 < len(grid):
        for col_c in range(c, c+3):
            ext_neighbors.append((r+2, col_c))
    if c > 0:
        for row_r in range(r, r+2):
            ext_neighbors.append((row_r, c-1))
    if c+3 < len(grid[0]):
        for row_r in range(r, r+2):
            ext_neighbors.append((row_r, c+3))

    all_zero = True
    for n in ext_neighbors:
        if grid[n[0]][n[1]] != 0:
            all_zero = False
            break
    return all_zero

